window.__finlexDocLoaded(10162,{"id":10162,"articles":[{"id":1000679,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Non-authoritative conceptual foundation guiding the FASB in developing US GAAP, covering the objective of financial reporting (Ch. 1), reporting entity (Ch. 2), qualitative characteristics (Ch. 3), elements (Ch. 4), recognition and derecognition (Ch. 5), measurement (Ch. 6, issued 2024), presentation (Ch. 7), and notes to financial statements (Ch. 8).","seq":0},{"id":1000680,"no":"CON 8 Ch. 1–8","heading":"Conceptual Foundation & 2024 Measurement Chapter","text":"• Fundamental Qualitative Characteristics (Ch. 3): Relevance (predictive/confirmatory value, materiality) and Faithful Representation (complete, neutral, free from error).\n• Elements of Financial Statements (Ch. 4): Asset = present right of an entity to an economic benefit; Liability = present obligation to transfer an economic benefit.\n• Measurement (Ch. 6, issued June 2024): Establishes entry price system vs. exit price system as the two overarching measurement frameworks.\n• Non-authoritative status: Concepts Statements do not override authoritative ASC guidance (ASC 105-10-05-3).","seq":1},{"id":1000681,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Largely converged with the IASB Conceptual Framework (2018), though FASB retains its own chapters on Measurement (2024) and Notes (Ch. 8) and places Concepts Statements strictly outside the authoritative GAAP hierarchy.","seq":2},{"id":1000682,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
